// Generates the plugin's `allow-<command>` / `deny-<command>` permissions under `permissions/autogenerated`.
const COMMANDS: &[&str] = &[
    "open_window",
    "close_window",
    "set_status",
    "windows",
    "attach",
    "input",
];

fn main() {
    tauri_plugin::Builder::new(COMMANDS).build();
}
